-- p13_collation, node 2. Generated by gen.py from special/src/p13_collation.sql.
-- Usage:  psql -X -q -v ON_ERROR_STOP=1 -d <database> -f p13_collation_node2.sql
--
-- Case P13: the sort rules of text differ (another glibc or ICU version,
-- another locale provider or default locale of the cluster).
-- Stand: two servers on different OS releases (for example glibc before and
--        after 2.28), or two clusters made by initdb with other locale options.
-- Run:   the same data on both.
-- Expect: sp.p13_sort_order stores the position of each string in the sort
--         order of its server. On equal rules the tables match; otherwise the
--         rows that changed places differ in pos_default. sp.p13_text_key has
--         the same rows on both nodes: it must match, although ranges of the
--         key select other rows on each node.

SET client_min_messages = warning;
SET TimeZone = 'UTC';
SET DateStyle = 'ISO, MDY';
SET IntervalStyle = 'postgres';
SET default_transaction_read_only = off;
CREATE SCHEMA IF NOT EXISTS sp;
DROP TABLE IF EXISTS sp.p13_sort_order, sp.p13_text_key;
CREATE TABLE sp.p13_sort_order (s text COLLATE "C" PRIMARY KEY, pos_default int, pos_c int);
INSERT INTO sp.p13_sort_order
	SELECT s, row_number() OVER (ORDER BY s COLLATE "default", s COLLATE "C"), row_number() OVER (ORDER BY s COLLATE "C")
	FROM unnest(ARRAY['a-a', 'a+a', 'aa', 'a a', 'A', 'a', 'B', 'b', '_x', '-x', 'x', '1', '10', '2', '1.5', 'Z', 'z',
		U&'\00E9', 'e', 'f', U&'\00E4', 'ae', 'af', U&'\00DF', 'ss', 'st', U&'\0451', U&'\0435', U&'\0436',
		U&'\0130', 'i', 'I', 'coop', 'co-op', 'co op', 'CO-OP', 'a.b', 'a_b', 'ab', U&'\4E2D', U&'\65E5', '']) s;
COMMENT ON TABLE sp.p13_sort_order IS 'P13: pos_default differs for the strings that the two servers sort in another order';

CREATE TABLE sp.p13_text_key (id text PRIMARY KEY, v text);
INSERT INTO sp.p13_text_key
	SELECT CASE WHEN i % 2 = 0 THEN chr(65 + i % 26) ELSE chr(97 + i % 26) END || (ARRAY['-', '+', '_', ' ', ''])[1 + i % 5] || lpad(i::text, 5, '0'), 'v' || i
	FROM generate_series(1, 5000) i;
COMMENT ON TABLE sp.p13_text_key IS 'P13: the same rows on both nodes: match, whatever the sort rules are';
